#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("ERROR");
        return 0;
    }
    const int MAX_STACK = 64;
    long stack[MAX_STACK];
    int top = 0;
    for (int i = 1; i < argc; ++i) {
        char *tok = argv[i];
        size_t len = strlen(tok);
        bool is_op = (len == 1 && strchr("+-*/", tok[0]) != NULL);
        if (is_op) {
            if (top < 2) {
                puts("ERROR");
                return 0;
            }
            long b = stack[--top];
            long a = stack[--top];
            long res;
            switch (tok[0]) {
                case '+':
                    res = a + b;
                    break;
                case '-':
                    res = a - b;
                    break;
                case '*':
                    res = a * b;
                    break;
                case '/':
                    if (b == 0) {
                        puts("ERROR");
                        return 0;
                    }
                    res = a / b;
                    break;
                default:
                    puts("ERROR");
                    return 0;
            }
            if (top >= MAX_STACK) {
                puts("ERROR");
                return 0;
            }
            stack[top++] = res;
        } else {
            char *endptr;
            long val = strtol(tok, &endptr, 10);
            if (endptr == tok || *endptr != '\0') {
                puts("ERROR");
                return 0;
            }
            if (top >= MAX_STACK) {
                puts("ERROR");
                return 0;
            }
            stack[top++] = val;
        }
    }
    if (top != 1) {
        puts("ERROR");
        return 0;
    }
    printf("%ld\n", stack[0]);
    return 0;
}
